import{_ as e,c as t,o as a,a2 as o}from"./chunks/framework.B3iQLowF.js";const r=JSON.parse('{"title":"BrandPulse - Data Generation Research Overview | Mohanpathi Portfolio","description":"A detailed look at how I prototyped data generation to fuel a 700k posts/sec system.","frontmatter":{"title":"BrandPulse - Data Generation Research Overview","description":"A detailed look at how I prototyped data generation to fuel a 700k posts/sec system."},"headers":[],"relativePath":"docs/brandpulse/implementation/research/data-generation/overview.md","filePath":"docs/brandpulse/implementation/research/data-generation/overview.md","lastUpdated":1741551076000}');const s=e({name:"docs/brandpulse/implementation/research/data-generation/overview.md"},[["render",function(e,r,s,i,n,l){return a(),t("div",null,r[0]||(r[0]=[o('<h1 id="data-generation-research-overview" tabindex="-1">Data Generation Research Overview <a class="header-anchor" href="#data-generation-research-overview" aria-label="Permalink to &quot;Data Generation Research Overview&quot;">​</a></h1><p>Building BrandPulse meant generating a flood of social media posts—think thousands of &quot;SuperCoffee&quot; tweets per second—to test a system that could handle real-time chaos at scale. This wasn’t about jumping straight to the finish line; it was a grind through prototypes to figure out how to create data fast, reliably, and without crashing my setup. Here’s the story of how I took it from a trickle to a torrent, step by step, laying the groundwork for a system that hits 700,000 posts per second.</p><h2 id="purpose-and-scope" tabindex="-1">Purpose and Scope <a class="header-anchor" href="#purpose-and-scope" aria-label="Permalink to &quot;Purpose and Scope&quot;">​</a></h2><p>The goal was simple but brutal: generate enough realistic posts to simulate a social media storm, then feed them into Kafka for processing. I needed speed, volume, and a touch of real-world flavor—like positive or negative vibes about SuperCoffee—without bogging down Node.js or my machine. These prototypes were my proving ground, where I tested ideas, hit limits, and refined the approach that eventually powered the <a href="./../../producer">final producer</a>.</p><h2 id="prototype-evolution" tabindex="-1">Prototype Evolution <a class="header-anchor" href="#prototype-evolution" aria-label="Permalink to &quot;Prototype Evolution&quot;">​</a></h2><p>Here’s how the journey unfolded—each version a step closer to the target:</p><ul><li><strong><a href="./v1">Version 1</a></strong>: Started with a basic setup generating 20K posts/sec, then scaled to 160K/sec using worker threads. A solid first leap—details <a href="./v1">here</a>.</li><li><strong><a href="./v2">Version 2</a></strong>: Pushed batch sizes higher, targeting 200K posts/sec. Learned to balance throughput with resource strain.</li><li><strong><a href="./v3">Version 3</a></strong>: Added randomization for sentiment and hit 600K posts/sec. Made it feel more like real social media chatter.</li><li><strong><a href="./v4">Version 4</a></strong>: Optimized generation logic, reaching 1M posts/sec. Efficiency became the name of the game but unstable.</li></ul><p><em>Note: These are the core steps, but the process was iterative—more versions could slot in as I dug deeper.</em></p><h2 id="key-milestones" tabindex="-1">Key Milestones <a class="header-anchor" href="#key-milestones" aria-label="Permalink to &quot;Key Milestones&quot;">​</a></h2><ul><li><strong>Starting Point</strong>: Version 1’s single-threaded run gave me 20K posts/sec—decent, but nowhere near enough for BrandPulse’s ambitions.</li><li><strong>Breakthrough</strong>: Worker threads in v1 unlocked parallel generation, jumping to 160K/sec. That’s when I knew I was onto something.</li><li><strong>Endgame</strong>: By v3/v4, I was generating close to 650K posts/sec, ready to hand off to Kafka and the downstream pipeline.</li></ul><h2 id="why-it-matters" tabindex="-1">Why It Matters <a class="header-anchor" href="#why-it-matters" aria-label="Permalink to &quot;Why It Matters&quot;">​</a></h2><p>This wasn’t just about making fake tweets—it was about proving I could build a data engine that scales. For a system like BrandPulse, where every second counts, nailing generation was critical. It’s the kind of challenge you tackle with grit and ingenuity—something I’ve learned growing up in India, where you don’t wait for perfect tools; you make it work with what you’ve got. These experiments fed directly into the <a href="./../../producer">final producer</a>, ensuring it could handle a real-world load.</p><h2 id="takeaways" tabindex="-1">Takeaways <a class="header-anchor" href="#takeaways" aria-label="Permalink to &quot;Takeaways&quot;">​</a></h2><ul><li><strong>Parallel Power</strong>: Single-threaded Node.js couldn’t cut it—spreading work across cores was a game-changer.</li><li><strong>Batch Smarts</strong>: Bigger batches boosted speed, but too big, and memory groaned. Finding the sweet spot took trial and error.</li><li><strong>Realistic Data</strong>: Adding sentiment and timestamps wasn’t just flair—it made testing legit.</li></ul><h2 id="dig-deeper" tabindex="-1">Dig Deeper <a class="header-anchor" href="#dig-deeper" aria-label="Permalink to &quot;Dig Deeper&quot;">​</a></h2><p>Want the full scoop? Start with <a href="./v1">Version 1</a> to see where it began, then check <a href="./../../issues-faced">Issues Faced</a> for the hiccups I hit and <a href="./../../lessons-learned">Lessons Learned</a> for what I’d do differently. This was about building something tough, practical, and ready for the big leagues—one prototype at a time.</p>',16)]))}]]);export{r as __pageData,s as default};
